const validationForm=document.getElementById("validation-demo"),validationSummary=document.getElementById("validation-summary"),validationRegion=document.getElementById("validation-region-id"),validationThreshold=document.getElementById("validation-threshold");const updateValidationField=(input,valid,message)=>{const field=input.closest(".validation-field"),output=field.querySelector(".validation-message");field.classList.toggle("invalid",!valid);field.classList.toggle("valid",valid);input.setAttribute("aria-invalid",String(!valid));output.className=`validation-message ${valid?"success":"error"}`;output.innerHTML=`<span aria-hidden="true">${valid?"✓":"×"}</span>${message}`};const validateDemo=()=>{const regionValid=/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(validationRegion.value.trim()),threshold=Number(validationThreshold.value),thresholdValid=validationThreshold.value!==""&&threshold>=0&&threshold<=1;updateValidationField(validationRegion,regionValid,regionValid?"Stable region ID is available.":"Use lowercase letters, numbers, and hyphens.");updateValidationField(validationThreshold,thresholdValid,thresholdValid?"Threshold is within the supported range.":"Enter a value from 0 to 1.");const issues=[!regionValid&&"Region ID is invalid.",!thresholdValid&&"Threshold must be between 0 and 1."].filter(Boolean);validationForm.classList.toggle("is-valid",issues.length===0);validationSummary.querySelector(".validation-summary-icon").textContent=issues.length?"!":"✓";validationSummary.querySelector("strong").textContent=issues.length?`${issues.length} issue${issues.length===1?"":"s"} prevent this plan from being applied`:"Plan is ready to apply";validationSummary.querySelector("p").textContent=issues.length?"Review the highlighted fields, then validate again.":"All required values passed validation.";validationSummary.querySelector("ul").hidden=issues.length===0;if(issues.length)validationSummary.querySelector("ul").innerHTML=issues.map(issue=>`<li>${issue}</li>`).join("");return issues.length===0};validationForm.addEventListener("submit",event=>{event.preventDefault();validateDemo()});document.getElementById("reset-validation-demo").addEventListener("click",()=>{validationRegion.value="";validationThreshold.value="1.4";validateDemo()});validationSummary.querySelectorAll("a").forEach(link=>link.addEventListener("click",()=>document.querySelector(link.getAttribute("href")).focus()));
const showcaseLinks=[...document.querySelectorAll('.showcase-nav-groups a[href^="#"]')],showcaseJump=document.getElementById("showcase-jump-select"),showcaseTargets=showcaseLinks.map(link=>document.querySelector(link.getAttribute("href"))).filter(Boolean);const setActiveShowcaseSection=id=>{showcaseLinks.forEach(link=>link.classList.toggle("active",link.getAttribute("href")===`#${id}`));if([...showcaseJump.options].some(option=>option.value===id))showcaseJump.value=id};showcaseJump.addEventListener("change",()=>{const target=document.getElementById(showcaseJump.value);if(target){target.scrollIntoView({behavior:"auto",block:"start"});history.replaceState(null,"",`#${showcaseJump.value}`);setActiveShowcaseSection(showcaseJump.value)}});const showcaseObserver=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible[0])setActiveShowcaseSection(visible[0].target.id)},{rootMargin:"-10% 0px -78% 0px",threshold:0});showcaseTargets.forEach(target=>showcaseObserver.observe(target));showcaseLinks.forEach(link=>link.addEventListener("click",()=>setActiveShowcaseSection(link.hash.slice(1))));
